SELECT d.diary_id,d.public_id,s.public_id AS space_public_id,d.author_id,d.title,d.diary_date, NULL AS content_html,LEFT(d.content_text,600) AS content_text,d.mood_key,d.visibility,d.locked, d.version,d.created_at,d.updated_at,d.deleted_at FROM diary d JOIN diary_space s ON s.space_id=d.space_id WHERE AND d.diary_date>=#{query.startDate} AND d.diary_date<=#{query.endDate} AND d.mood_key=#{query.mood}
AND MATCH(d.title,d.content_text) AGAINST(#{query.keyword} IN NATURAL LANGUAGE MODE)
AND EXISTS (SELECT 1 FROM diary_tag dt JOIN tag t ON t.tag_id=dt.tag_id WHERE dt.diary_id=d.diary_id AND t.public_id=#{tagPublicId})
AND (d.diary_date<#{query.cursorDate} OR (d.diary_date=#{query.cursorDate} AND d.diary_id<#{query.cursorId}))
ORDER BY d.diary_date DESC,d.diary_id DESC LIMIT #{query.limit}

SELECT COUNT(*)
FROM diary d
WHERE 
AND d.diary_date>=#{query.startDate}
AND d.diary_date<=#{query.endDate}
AND d.mood_key=#{query.mood}

    AND MATCH(d.title,d.content_text) AGAINST(#{query.keyword} IN NATURAL LANGUAGE MODE)


    AND EXISTS (SELECT 1 FROM diary_tag dt JOIN tag t ON t.tag_id=dt.tag_id
                WHERE dt.diary_id=d.diary_id AND t.public_id=#{tagPublicId})

SELECT asset_id AS internal_id,public_id FROM media_asset
WHERE space_id=#{spaceId} AND deleted_at IS NULL AND status='READY' AND public_id IN
#{id}
